with a as( select DISTINCT aa.inspect_id ,aa.should_inspect_num from ${inspectIntoDispatcherTable} aa where aa.delete_flag = false GROUP BY aa.inspect_id ,aa.should_inspect_num ) , b as( select a.inspect_id,sum(a.should_inspect_num) as should_inspect_num from a GROUP BY a.inspect_id ), c as( select cc.inspect_id, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as passed_num,sum(cc.un_passed_num) as un_passed_num from ${inspectIntoReportTable} cc GROUP BY cc.inspect_id ), d as( select aa.inspect_id,aa.inspect_type,string_agg(CAST(bb.staff_sign as TEXT),',') as inspectUserName from ${inspectIntoDispatcherTable} aa , ${staffTable} bb where aa.inspect_user_code = bb.primary_key GROUP BY aa.inspect_id,aa.inspect_type ) select * from ( select aa.buss_number,aa.create_time,aa.batch,aa.product_flag, aa.main_id,aa.model,aa.pcs_name,aa.related_name,aa.related_code,aa.related_type,aa.product_or_part,aa.product_or_part_name, aa.batch_num,aa.report_batch_no, aa.procedure_name,aa.operator_user_code,aa.task_num,aa.overdue_date,aa.status,aa.remark,aa.primary_key as primaryKeyValue,aa.enterprise_code,aa.primary_key, b.should_inspect_num,c.inspect_num, c.passed_num , c.un_passed_num , ROUND((c.passed_num/c.inspect_num) * 100,2) as passed_rate,d.inspectUserName,aa.check_items,d.inspect_type,e.status as approve_status from ${inspectIntoTable} aa LEFT JOIN b on aa.primary_key = b.inspect_id LEFT JOIN c on aa.primary_key = c.inspect_id LEFT JOIN d on aa.primary_key = d.inspect_id left join ${approveTable} e on aa.primary_key = e.inspect_main_id where aa.delete_flag = false ) t where t.enterprise_code = #{enterpriseCode}
AND ( t.buss_number like concat('%', #{data.bussNumber}, '%') or t.batch like concat('%',#{data.bussNumber}, '%') )
AND t.product_or_part_name like concat('%',#{data.productOrPartName}, '%')
AND t.model like concat('%',#{data.model}, '%')
AND t.related_name like concat('%',#{data.relatedName}, '%')
AND t.status = #{data.status}
AND t.overdue_date >= #{data.beginDate}
AND t.overdue_date <= #{data.endDate}
AND t.operator_user_code = #{data.operatorUserCode}
AND exists ( select 1 from ${inspectIntoDispatcherTable} b where b.inspect_user_code IN
#{userCode}
and b.inspect_id=t.primary_key)
AND t.passed_rate >= #{data.passRate}
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",data.partUnityNo)}
and ${dynamicTableNameProxy.getProductPartSearchObj("t.product_or_part",data.searchName)}
order by t.create_time desc

WITH t as( select cc.inspect_id, batch_no,status, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as passed_num,sum(cc.un_passed_num) as un_passed_num from ${inspectIntoReportTable} cc where cc.inspect_user = #{data.inspectUserCode[0]} GROUP BY cc.inspect_id,batch_no,status ) select * from ( select b.buss_number,b.batch,b.product_flag, b.model,b.pcs_name,b.related_name,b.related_code,b.related_type,b.product_or_part,b.product_or_part_name, b.batch_num,b.report_batch_no, b.procedure_name,b.operator_user_code,b.task_num,a.finish_date as overdue_date,t.status,b.status as main_status, a.remark,b.enterprise_code,b.create_time,b.check_items, t.inspect_num,t.passed_num,t.un_passed_num, ROUND((t.passed_num/t.inspect_num) * 100,2) as passed_rate, a.primary_key as primaryKeyValue,a.allocation_num as should_inspect_num,a.batch_no,a.inspect_id as mainId, e.status as approve_status from ${inspectIntoDispatcherTable} a LEFT JOIN ${inspectIntoTable} b on a.inspect_id = b.primary_key LEFT JOIN t on t.inspect_id = a.inspect_id and t.batch_no = a.batch_no left join ${approveTable} e on b.primary_key = e.inspect_main_id where a.inspect_user_code = #{data.inspectUserCode[0]} and a.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode}
AND ( tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
and ${dynamicTableNameProxy.getXiHangPartQuery("tt.product_or_part","xihang",data.partUnityNo)}
AND tt.product_or_part_name like concat('%',#{data.productOrPartName}, '%')
AND tt.model like concat('%',#{data.model}, '%')
AND tt.related_name like concat('%',#{data.relatedName}, '%')
AND (tt.status is null or tt.status = 30) AND tt.main_status != 50
AND (tt.status = #{data.status} or tt.main_status = #{data.status})
AND tt.overdue_date >= #{data.beginDate}
AND tt.overdue_date <= #{data.endDate}
AND tt.operator_user_code = #{data.operatorUserCode}
AND tt.passed_rate >= #{data.passRate}
and ${dynamicTableNameProxy.getProductPartSearchObj("tt.product_or_part",data.searchName)}
order by tt.create_time desc

with t as (select inspect_id, a.should_inspect_num from ${inspectIntoDispatcherTable} a GROUP BY a.inspect_id, a.should_inspect_num) select * from( select b.batch_num,a.primary_key as primaryKeyValue, b.procedure_name,b.buss_number,b.batch,b.product_flag, b.pcs_name,b.related_name,b.related_code,b.related_type, b.product_or_part,b.model, b.product_or_part_name, b.operator_user_code,d.staff_sign as operatorUserName, b.task_num, b.overdue_date, t.should_inspect_num, a.finish_date, a.inspect_type, a.inspect_ratio, a.passed_num, a.inspect_num as inspectNum, a.un_passed_num, a.create_time, a.inspect_id as mainId, a.batch_no, a.inspect_user,c.staff_sign as inspectUserName, a.enterprise_code, a.remark, ROUND((a.passed_num/a.inspect_num) * 100,2) as pass_rate from ${inspectIntoReportTable} a inner join t on t.inspect_id = a.inspect_id LEFT JOIN ${inspectIntoTable} b on a.inspect_id = b.primary_key LEFT JOIN ${staffTable} c on a.inspect_user = c.primary_key LEFT JOIN ${staffTable} d on b.operator_user_code = d.primary_key where a.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode}
AND (tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
AND tt.product_or_part_name like concat('%',#{data.productOrPartName}, '%')
AND tt.model like concat('%',#{data.model}, '%')
and ${dynamicTableNameProxy.getXiHangPartQuery("tt.product_or_part","xihang",data.partUnityNo)}
AND tt.related_name like concat('%',#{data.relatedName}, '%')
AND tt.create_time >= #{data.beginDate}
AND tt.create_time <= #{data.endDate}
AND tt.operator_user_code = #{data.operatorUserCode}
AND tt.inspect_user IN
#{userCode}
AND tt.pass_rate >= #{data.passRate}
AND tt.inspect_type = #{data.inspectType}
and ${dynamicTableNameProxy.getProductPartSearchObj("tt.product_or_part",data.searchName)}
AND primaryKeyValue IN
#{code}
order by tt.create_time desc
limit #{data.limitNum}

with t as ( select inspect_id, sum(a.allocation_num) as should_inspect_num from ${inspectIntoDispatcherTable} a where a.enterprise_code = #{enterpriseCode} and a.inspect_user_code = #{data.inspectUserCode[0]} GROUP BY inspect_id ) select * from( select b.batch_num,a.primary_key as primaryKeyValue, b.procedure_name,b.buss_number,b.batch,b.product_flag, b.pcs_name,b.related_name,b.related_code,b.related_type, b.product_or_part, b.product_or_part_name,b.model, b.operator_user_code,d.staff_sign as operatorUserName, b.task_num, b.overdue_date, t.should_inspect_num, a.finish_date, a.inspect_type, a.inspect_ratio, a.passed_num, a.inspect_num, a.un_passed_num, a.create_time, a.inspect_id as mainId, a.batch_no, a.inspect_user,c.staff_sign as inspectUserName, a.enterprise_code, a.remark, ROUND((a.passed_num/a.inspect_num) * 100,2) as pass_rate from ${inspectIntoReportTable} a inner join t on t.inspect_id = a.inspect_id LEFT JOIN ${inspectIntoTable} b on a.inspect_id = b.primary_key LEFT JOIN ${staffTable} c on a.inspect_user = c.primary_key LEFT JOIN ${staffTable} d on b.operator_user_code = d.primary_key where a.delete_flag = false and b.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode} and tt.inspect_user = #{data.inspectUserCode[0]}
AND ( tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
AND tt.product_or_part_name like concat('%',#{data.productOrPartName}, '%')
AND tt.model like concat('%',#{data.model}, '%')
AND tt.related_name like concat('%',#{data.relatedName}, '%')
AND tt.create_time >= #{data.beginDate}
AND tt.create_time <= #{data.endDate}
AND tt.operator_user_code = #{data.operatorUserCode}
and ${dynamicTableNameProxy.getXiHangPartQuery("tt.product_or_part","xihang",data.partUnityNo)}
AND tt.pass_rate >= #{data.passRate}
AND tt.inspect_type = #{data.inspectType}
and ${dynamicTableNameProxy.getProductPartSearchObj("tt.product_or_part",data.searchName)}
AND primaryKeyValue IN
#{code}
order by tt.create_time desc
limit #{data.limitNum}

